package com.wheelwright.evidence.v2.portfolio;
import org.junit.jupiter.api.Test;import java.time.Instant;
import static org.assertj.core.api.Assertions.*;import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
class PortfolioPayoffPlotTest {
 @Test void samplesPreserveSlopingTailAndExactAuthoritativeAffineValueWithoutBasisOrRiskInference(){
  var e=obj();e.set("spot",unknown("PRICE",Instant.EPOCH.toString(),"MARKET_OBSERVATION_MISSING"));var p=obj().put("status","QUALIFIED");var g=obj().put("valueKind","TERMINAL_VALUE").put("priceCurrency","USD");g.set("boundaries",array().add(obj().put("price","100").put("value","10000")));g.set("segments",array().add(obj().put("lower","0").put("upper","100").put("slope","100").put("intercept","0")).add(obj().put("lower","100").putNull("upper").put("slope","0").put("intercept","10000")));p.set("geometry",g);e.set("payoff",p);PortfolioPayoffPlot.apply(e);assertThat(g.path("displayPoints")).hasSize(3);assertThat(g.at("/displayPoints/0/price").asText()).isEqualTo("85");assertThat(g.at("/displayPoints/0/value").asText()).isEqualTo("8500");assertThat(g.at("/displayPoints/2/value").asText()).isEqualTo("10000");assertThat(g.path("valueKind").asText()).isEqualTo("TERMINAL_VALUE");
 }
 @Test void noSamplesAreManufacturedForUnsupportedOrEmptyGeometry(){var e=obj();e.set("payoff",obj().put("status","UNSUPPORTED").putNull("geometry"));PortfolioPayoffPlot.apply(e);assertThat(e.at("/payoff/geometry").isNull()).isTrue();}
 @Test void oneStrikeKeepsContextOnBothSidesWithoutChangingCurveEconomics(){var c=PortfolioMoneynessTest.construction("CALL");((com.fasterxml.jackson.databind.node.ObjectNode)c.at("/composition/children/1/terms")).put("strike","15");var e=PortfolioMoneynessTest.evaluation(c,"12.4",PortfolioMoneynessTest.NOW.minusSeconds(1));var g=e.at("/payoff/geometry");assertThat(g.at("/displayPoints/0/price").asText()).isEqualTo("10.15");assertThat(g.path("displayPoints").get(g.path("displayPoints").size()-1).path("price").asText()).isEqualTo("17.25");assertThat(g.at("/spotPoint/value").asText()).isEqualTo("1240");assertThat(g.at("/segments/0/slope").asText()).isEqualTo("100");assertThat(g.at("/segments/1/intercept").asText()).isEqualTo("1500");}

 @Test void aKnownBasisSampleKeepsItsGrossExpirationMeaningWithoutBecomingCurrentPnl(){var c=PortfolioMoneynessTest.construction("CALL");((com.fasterxml.jackson.databind.node.ObjectNode)c.at("/composition/children/0/allocation")).set("basis",metric(new java.math.BigDecimal("1000"),"MONEY","USD",PortfolioMoneynessTest.NOW.toString(),"CONTROLLED_BASIS","QUALIFIED",array()));((com.fasterxml.jackson.databind.node.ObjectNode)c.at("/composition/children/1/allocation")).set("basis",metric(new java.math.BigDecimal("10"),"MONEY","USD",PortfolioMoneynessTest.NOW.toString(),"CONTROLLED_BASIS","QUALIFIED",array()));var e=PortfolioMoneynessTest.evaluation(c,"9",PortfolioMoneynessTest.NOW);assertThat(e.at("/payoff/geometry/valueKind").asText()).isEqualTo("GROSS_PL");assertThat(e.at("/payoff/geometry/spotPoint/value").asText()).isEqualTo("-90");assertThat(e.at("/grossUnrealizedPl/value").isNull()).isTrue();}
 @Test void multipleStrikeViewportKeepsItsExistingPadding(){var c=PortfolioMoneynessTest.construction("CALL");var kids=(com.fasterxml.jackson.databind.node.ArrayNode)c.at("/composition/children");kids.remove(0);var other=((com.fasterxml.jackson.databind.node.ObjectNode)kids.get(0)).deepCopy();other.put("side","LONG");((com.fasterxml.jackson.databind.node.ObjectNode)other.path("terms")).put("strike","11");kids.add(other);var e=PortfolioMath.evaluate(c,java.util.Map.of(),PortfolioMoneynessTest.NOW);e.set("spot",metric(new java.math.BigDecimal("9"),"PRICE","USD",PortfolioMoneynessTest.NOW.toString(),"CONTROLLED_MIDPOINT","QUALIFIED",array()));PortfolioPayoffPlot.apply(e);var points=e.at("/payoff/geometry/displayPoints");assertThat(points.get(0).path("price").asText()).isEqualTo("8.7");assertThat(points.get(points.size()-1).path("price").asText()).isEqualTo("11.3");}

}
